import re

def word_frequencies(text: str) -> dict:
    """
    Return a dictionary mapping each lowercase word in *text* to its frequency,
    ignoring punctuation and other non‑alphabetic characters.
    """
    # Find all sequences of letters, convert to lower case
    words = re.findall(r"[A-Za-z]+", text.lower())

    freq = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1
    return freq


